<?php
/** Minimal append helper; validates correlation-first identity. */
function opt($n,$d=''){global $argv;$p='--'.$n.'=';foreach($argv as $a)if(strpos($a,$p)===0)return substr($a,strlen($p));return $d;}function bad($m){fwrite(STDERR,$m.PHP_EOL);exit(2);} $md=realpath(dirname(__DIR__,3));$id=opt('id');$type=opt('type');$stage=opt('stage');$attempt=opt('attempt');$baseline=opt('baseline');$path=opt('path');if(!$id||!$type||!$stage||!$attempt||!$baseline||!$path)bad('Required --id --type --stage --attempt --baseline --path');if(!preg_match('/^MD-B\d{2}$/',$stage)||!preg_match('/^MD-B\d{2}-A\d{3}$/',$attempt))bad('Bad stage/attempt');$f=fopen($md.'/records/WORK_RECORD_REGISTRY.csv','a');fputcsv($f,array($id,$type,$stage,$attempt,$attempt,$baseline,'ISSUED',$path,'','','','','',date(DATE_ATOM),''));fclose($f);echo 'REGISTERED '.$id.PHP_EOL;
